def _n(identifier, kind=GraphNodeType.HYPOTHESIS, status=GraphStatus.ACTIVE, statement=None):
    return GraphNode(id=identifier, node_type=kind, statement=statement or f"A case object requiring review: {identifier}.", status=status)

def _e(source, relation, target):
    return GraphEdge(id=f"{source}_{relation.value.upper()}_{target}", source_id=source, relation=relation, target_id=target)

def _b(issue_id, basis_id, source_kind, **kwargs):
    return PublicBasisRequirement(issue_id=issue_id, basis_id=basis_id, source_kind=source_kind, **kwargs)

def _f(identifier, nodes, edges, focus, issues, description, basis, **kwargs):
    graph = CaseGraph(case_id=identifier, nodes={n.id: n for n in nodes}, edges={e.id: e for e in edges})
    return TrajectoryFixture(fixture_id=identifier, description=description, graph=graph, focus=InvestigationFocus(node_id=focus), issues=issues, public_basis=basis, basis_audit_required=True, required_edges=[(e.source_id, e.relation.value, e.target_id) for e in edges], step_cap=kwargs.pop("step_cap", 8), **kwargs)

