    seq3 = _f("SEQ3", [_n("H1", statement="The broader explanation remains useful."), _n("H1.1", statement="A highly specific version of the broader explanation."), _n("H2", statement="A competing explanation with a live unresolved question."), _n("U2", u, statement="Which competing explanation better fits the record?")], [_e("H1.1", EdgeRelation.SPECIALIZES, "H1"), _e("U2", EdgeRelation.TARGETS, "H2")], "H1.1", [StewardIssue(issue_id="I1", kind=IssueKind.OVER_SPECIFIC_FOCUS, target_node_id="H1.1", parent_node_id="H1"), StewardIssue(issue_id="I2", kind=IssueKind.NEGLECTED_ACTIVE, target_node_id="H2")], "The specific H1.1 branch has no additional unresolved local question, while broader H1 remains meaningful. H2 has an active unresolved comparison question.", [_b("I1", "B1", PublicBasisKind.GRAPH_EDGE, source_id="H1.1", relation="specializes", target_id="H1"), _b("I1", "B2", PublicBasisKind.SCENARIO_FACT, fact="The specific H1.1 branch has no additional unresolved local question"), _b("I2", "B3", PublicBasisKind.GRAPH_EDGE, source_id="U2", relation="targets", target_id="H2")], must_remain_active_node_ids={"H1.1"})
